import ast, pathlib
def is_stub(fn):
    body = [s for s in fn.body if not (isinstance(s, ast.Expr) and isinstance(s.value, ast.Constant) and isinstance(s.value.value, str))]
    if len(body) != 1 or not isinstance(body[0], ast.Raise):
        return False
    exc = body[0].exc
    name = getattr(exc, \"func\", exc)
    return isinstance(name, ast.Name) and name.id == \"NotImplementedError\"
n = 0
for f in pathlib.Path(\"src/econflow_engine/wrappers\").rglob(\"*.py\"):
    if f.name == \"__init__.py\":
        continue
    for node in ast.walk(ast.parse(f.read_text())):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith(\"_\") and not is_stub(node):
            n += 1
print(n)
"

commands.min_signature_name_modules:
python3 -c "
import ast, pathlib
named = 0
for path in sorted(pathlib.Path('src/econflow_engine/wrappers').rglob('*.py')):
    if path.name == '__init__.py':
        continue
    hit = False
    for fn in ast.parse(path.read_text(encoding='utf-8')).body:
        if not isinstance(fn, ast.FunctionDef) or fn.name.startswith('_'):
            continue
        for arg in fn.args.kwonlyargs:
            if arg.annotation is None:
                continue
            hit = hit or any(isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id in ('pd', 'np') for n in ast.walk(arg.annotation))
    named += hit
print(named)
"

commands.min_handle_only_calls:
python3 -c "
import ast, pathlib
handles = {'pd.Series', 'pd.DataFrame', 'np.ndarray'}
calls = 0
for path in sorted(pathlib.Path('src/econflow_engine/wrappers').rglob('*.py')):
    if path.name == '__init__.py':
        continue
    for fn in ast.parse(path.read_text(encoding='utf-8')).body:
        if not isinstance(fn, ast.FunctionDef) or fn.name.startswith('_'):
            continue
        required = {ast.unparse(a.annotation) if a.annotation else '' for a, d in zip(fn.args.kwonlyargs, fn.args.kw_defaults, strict=True) if d is None}
        if required and required <= handles:
            calls += 1
print(calls)
"
